-- WWII_HISTORY rewrite: retires the old PERSON/PLACE/THING/EVENT/DATE x
-- ALLIED/AXIS structure (peer-pulled distractors) in favor of general-
-- knowledge questions, each carrying its own curated 6-answer wrong_answers
-- pool. 3 of the 6 are drawn at random each time the question is served, so
-- the same question can show a different (and sometimes tougher) trio of
-- foils on a replay. subcategory/faction are left NULL -- this mechanism
-- doesn't need peer grouping at all.
--
-- Requires the wrong_answers column (see the ALTER TABLE below, safe to
-- run even if it already exists).

ALTER TABLE questions ADD COLUMN IF NOT EXISTS wrong_answers TEXT[];

DELETE FROM questions WHERE category = 'WWII_HISTORY';

